/* Token Radar v3 — bright, modern dashboard theme. */
:root {
  --bg: #f4f6fb;
  --panel: #ffffff;
  --ink: #17233b;
  --dim: #5b6b85;
  --line: #e3e8f2;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --gold: #b45309;
  --gold-bg: #fef3c7;
  --green: #059669;
  --green-bg: #d1fae5;
  --red: #dc2626;
  --red-bg: #fee2e2;
  --mono: ui-monospace, "SF Mono", Menlo, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --shadow: 0 1px 3px rgba(23, 35, 59, 0.08), 0 4px 14px rgba(23, 35, 59, 0.06);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 400 15px/1.5 var(--sans); }

.shell { max-width: 1240px; margin: 0 auto; padding: 20px 24px 64px; }

/* Header band */
.top {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 12px;
  padding: 18px 0 14px; border-bottom: 2px solid var(--accent); margin-bottom: 4px;
}
.brand { font-family: var(--mono); font-size: 15px; font-weight: 700; color: var(--accent); letter-spacing: 0.06em; }
.brand .dot { color: var(--gold); }
.meta { color: var(--dim); font-size: 13px; }

/* Summary stat cards */
.facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; padding: 18px 0; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; box-shadow: var(--shadow); }
.fact b { display: block; font-family: var(--mono); font-size: 22px; color: var(--accent); }
.fact span { font-size: 12px; color: var(--dim); text-transform: uppercase; letter-spacing: 0.05em; }

/* Controls */
.controls { display: flex; flex-wrap: wrap; gap: 10px; padding: 6px 0 14px; align-items: center; }
.controls input, .controls select {
  background: var(--panel); color: var(--ink); border: 1px solid var(--line);
  border-radius: 8px; padding: 9px 14px; font: inherit; box-shadow: var(--shadow);
}
.controls input:focus, .controls select:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
.controls .meta { margin-left: auto; }

/* Table */
table { width: 100%; border-collapse: separate; border-spacing: 0; background: var(--panel); border-radius: 12px; overflow: hidden; box-shadow: var(--shadow); border: 1px solid var(--line); }
th {
  text-align: left; color: var(--dim); font-weight: 600; font-size: 12px; text-transform: uppercase;
  letter-spacing: 0.06em; padding: 12px 14px; border-bottom: 2px solid var(--line);
  background: var(--panel); cursor: pointer; user-select: none; white-space: nowrap; position: sticky; top: 0;
}
th:hover { color: var(--accent); }
th.sorted { color: var(--accent); }
th .arrow { font-size: 10px; margin-left: 3px; }
td { padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: top; }
tr.row:last-child td { border-bottom: none; }
tr.row:hover td { background: var(--accent-soft); cursor: pointer; }
tr.top3 td:first-child { box-shadow: inset 3px 0 0 var(--gold); }
.rank { font-family: var(--mono); color: var(--dim); font-weight: 700; }
tr.top3 .rank { color: var(--gold); }
td.num { font-family: var(--mono); text-align: right; white-space: nowrap; }
td .name { font-weight: 600; }
td .sub { display: block; font-size: 12px; color: var(--dim); margin-top: 2px; }
.iv { font-weight: 700; color: var(--accent); }

.chip { display: inline-block; background: var(--accent-soft); color: var(--accent); border-radius: 10px; padding: 1px 9px; font-size: 12px; margin-right: 4px; white-space: nowrap; }
.up { color: var(--green); font-weight: 600; }
.down { color: var(--red); font-weight: 600; }

/* Detail view */
.detail { background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 28px; box-shadow: var(--shadow); margin-top: 8px; }
.detail h2 { font-size: 26px; margin: 0 0 4px; }
.detail .meta { margin-bottom: 18px; }
.detail .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin: 18px 0; }
.detail .fact b { font-size: 19px; }
.detail h3 { font-size: 16px; margin: 22px 0 10px; color: var(--ink); border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.steps { margin: 0; padding-left: 22px; }
.steps li { margin-bottom: 10px; }
.back { background: var(--panel); border: 1px solid var(--line); color: var(--accent); border-radius: 8px; padding: 8px 16px; cursor: pointer; font: inherit; margin-bottom: 14px; }
.back:hover { background: var(--accent-soft); }

.foot { color: var(--dim); font-size: 12px; padding-top: 28px; max-width: 80ch; }

@media (max-width: 720px) {
  .shell { padding: 12px 12px 48px; }
  .detail { padding: 18px; }
  table { font-size: 13px; }
  td, th { padding: 8px 8px; }
}
